import{_ as e,o as a,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"声誉 Reputation","description":"信任是商业的命脉，破坏它需要几十年，修复它需要几百年","frontmatter":{"title":"声誉 Reputation","description":"信任是商业的命脉，破坏它需要几十年，修复它需要几百年"},"headers":[],"relativePath":"02_concepts/reputation.md","filePath":"02_concepts/reputation.md"}'),l={name:"02_concepts/reputation.md"};function p(i,t,n,h,s,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="声誉-reputation" tabindex="-1">声誉 Reputation <a class="header-anchor" href="#声誉-reputation" aria-label="Permalink to &quot;声誉 Reputation&quot;">​</a></h1><blockquote><p>&quot;信任是商业的命脉，破坏它需要几十年，修复它需要几百年。&quot; —— <a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1991年</p></blockquote><p>声誉是<a href="/04_people/沃伦·巴菲特">巴菲特</a>最珍视的无形资产，也是他在选择投资标的和管理旗下企业时的首要考量。他曾说：&quot;建立一个好名声需要二十年，毁掉它只需要五分钟。&quot;这句话不只是警句，而是他几十年商业生涯的真实写照。</p><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1991年/核心总结">核心总结</a></strong></td><td style="text-align:left;">所罗门危机：&quot;我不是来当CEO的，我是来保护声誉的&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结">核心总结</a></strong></td><td style="text-align:left;">信任与金融危机</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2014年/核心总结">核心总结</a></strong></td><td style="text-align:left;">声誉与长期竞争优势</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2019年/核心总结">核心总结</a></strong></td><td style="text-align:left;">继任安排：保护伯克希尔的声誉遗产</td></tr></tbody></table><hr><h2 id="一、声誉是巴菲特最核心的投资标准之一" tabindex="-1">一、声誉是巴菲特最核心的投资标准之一 <a class="header-anchor" href="#一、声誉是巴菲特最核心的投资标准之一" aria-label="Permalink to &quot;一、声誉是巴菲特最核心的投资标准之一&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>选择投资或收购一家企业时，首要考量往往不是财务数据，而是<strong>管理层是否诚信</strong>。</p><blockquote><p>&quot;我们只和我们喜欢、欣赏的人合作。这个政策不仅最大化好结果概率，还能让我们过得特别开心。和让你胃不舒服的人合作，就像为了钱结婚，本来就不对。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1986年致股东信</p></blockquote><p><strong><a href="/04_people/沃伦·巴菲特">巴菲特</a>的声誉筛选标准：</strong></p><ol><li>管理层是否对股东坦诚？——即使坏消息也如实报告</li><li>管理层是否只做自己理解的业务？——不欺骗自己</li><li>管理层是否把声誉放在利润之上？——&quot;如果要把声誉和利润选一个，我们选声誉&quot;</li></ol><hr><h2 id="二、所罗门危机-声誉保护的经典案例" tabindex="-1">二、所罗门危机：声誉保护的经典案例 <a class="header-anchor" href="#二、所罗门危机-声誉保护的经典案例" aria-label="Permalink to &quot;二、所罗门危机：声誉保护的经典案例&quot;">​</a></h2><p>1991年，<a href="/04_people/沃伦·巴菲特">巴菲特</a>接到了他一生中最困难的一个电话——所罗门公司濒临破产边缘，他被要求出面拯救。</p><blockquote><p>&quot;我不是来当CEO的。我是所罗门的最大债权人，我来这里是为了保护它的声誉，保护它的客户，保护它的员工。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1991年新闻发布会的原话</p></blockquote><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>在所罗门的行动，完全围绕&quot;声誉保护&quot;展开：</p><ul><li>第一时间向监管机构坦白违规行为</li><li>更换有问题的管理层</li><li>重建合规体系</li><li>在国会作证，维护公司信誉</li></ul><p>最终，所罗门在<a href="/04_people/沃伦·巴菲特">巴菲特</a>的领导下，不仅存活下来，还创下了当时的历史最高税前利润。</p><blockquote><p>&quot;所罗门的教训告诉我们：声誉比短期利润重要得多。那些为了短期利益而损害声誉的人，最终会付出沉重代价。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，1992年致股东信</p></blockquote><hr><h2 id="三、金融危机中的声誉考验" tabindex="-1">三、金融危机中的声誉考验 <a class="header-anchor" href="#三、金融危机中的声誉考验" aria-label="Permalink to &quot;三、金融危机中的声誉考验&quot;">​</a></h2><p>2008年金融危机期间，<a href="/04_people/沃伦·巴菲特">巴菲特</a>的声誉成为<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>最强大的竞争优势：</p><blockquote><p>&quot;当信贷市场冻结时，银行纷纷倒闭或被接管。<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>凭借AAA信用评级和充足的现金储备，成为少数几家能够向市场注入流动性的机构。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2008年致股东信</p></blockquote><p><strong>为什么<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>能在危机中获得这种地位？</strong></p><p>答案正是几十年积累的声誉：</p><ul><li>承诺兑现——<a href="/04_people/沃伦·巴菲特">巴菲特</a>说会救助高盛，他做到了</li><li>财务透明——<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>从不隐瞒风险</li><li>长期主义——投资者知道<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>不会为了短期利益牺牲长期信誉</li></ul><blockquote><p>&quot;2008年，市场最需要的不是钱，是信心。而信心来自声誉。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2009年致股东信</p></blockquote><hr><h2 id="四、声誉与护城河的关系" tabindex="-1">四、声誉与护城河的关系 <a class="header-anchor" href="#四、声誉与护城河的关系" aria-label="Permalink to &quot;四、声誉与护城河的关系&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>将声誉视为护城河的重要组成部分：</p><blockquote><p>&quot;真正持久的护城河，来自企业的文化和声誉。一个为了利润而欺骗客户的企业，即使有再强的品牌，终将被客户抛弃。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2014年致股东信</p></blockquote><p><strong>声誉护城河的构成：</strong></p><ol><li><strong>诚信文化</strong>——管理层对股东、对客户、对员工的承诺始终如一</li><li><strong>客户信任</strong>——品牌代表可靠的产品和服务</li><li><strong>员工忠诚</strong>——优秀人才愿意留在有诚信的企业</li><li><strong>监管信任</strong>——监管机构相信企业会遵守规则</li></ol><hr><h2 id="五、声誉的继任安排" tabindex="-1">五、声誉的继任安排 <a class="header-anchor" href="#五、声誉的继任安排" aria-label="Permalink to &quot;五、声誉的继任安排&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特">巴菲特</a>在2020年明确表示，<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>的继任安排首要目标是<strong>保护声誉遗产</strong>：</p><blockquote><p>&quot;我和查理已经制定了详细的继任计划。无论谁成为下一任CEO，我们的第一使命是保护<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>的声誉和文化。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2020年致股东信</p></blockquote><p><strong><a href="/04_people/沃伦·巴菲特">巴菲特</a>对继任者的唯一要求：</strong></p><blockquote><p>&quot;找一个会把<a href="/03_companies/伯克希尔哈撒韦">伯克希尔</a>的声誉看得比任何东西都重要的人。能力可以培养，声誉一旦失去，就永远回不来了。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特">沃伦·巴菲特</a>，2019年致股东信</p></blockquote><hr><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>内容</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>声誉是利益相关者对企业诚信和可靠性的集体认知</td></tr><tr><td><strong>建立</strong></td><td>需要几十年的一致性行为——说到做到</td></tr><tr><td><strong>破坏</strong></td><td>一个错误决定即可造成严重损害</td></tr><tr><td><strong>商业价值</strong></td><td>声誉是最宽的护城河，无法被复制或购买</td></tr><tr><td><strong><a href="/04_people/沃伦·巴菲特">巴菲特</a>标准</strong></td><td>&quot;声誉第一，利润第二&quot;</td></tr></tbody></table><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./management">管理层 (Management)</a> — 诚信是优秀管理者的第一标准</li><li><a href="./corporate-governance">公司治理 (Corporate Governance)</a> — 声誉需要制度保障</li><li><a href="./moat">护城河 (Moat)</a> — 声誉是最难复制的护城河</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=核心总结">1991年：核心总结</a> → <a href="/01_letters/1991年/翻译">/01_letters/1991年/翻译</a></li><li><a href="/search?q=核心总结">2008年：核心总结</a> → <a href="/01_letters/2008年/翻译">/01_letters/2008年/翻译</a></li><li><a href="/search?q=核心总结">2014年：核心总结</a> → <a href="/01_letters/2014年/翻译">/01_letters/2014年/翻译</a></li><li><a href="/search?q=核心总结">2019年：核心总结</a> → <a href="/01_letters/2019年/翻译">/01_letters/2019年/翻译</a></li></ul>',49)])])}const f=e(l,[["render",p]]);export{c as __pageData,f as default};
